[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WellSource — Expert health guidance you can trust</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<link href="https://cdn.jsdelivr.net/npm/remixicon@4.1.0/fonts/remixicon.css" rel="stylesheet">
<style>
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --primary: #02838D;
  --primary-dark: #026A72;
  --primary-light: #E6F5F6;
  --primary-50: #F0FAFA;
  --charcoal: #231F20;
  --charcoal-light: #4A4546;
  --white: #FFFFFF;
  --gray-50: #FAFAF9;
  --gray-100: #F5F5F4;
  --gray-200: #E7E5E4;
  --gray-300: #D6D3D1;
  --gray-400: #A8A29E;
  --gray-500: #78716C;
  --gray-600: #57534E;
  --coral: #E8635A;
  --coral-dark: #D4504A;
  --coral-light: #FEF0EF;
  --amber: #D4930D;
  --amber-light: #FFF8E6;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.07), 0 2px 4px rgba(0,0,0,0.04);
  --shadow-lg: 0 10px 30px rgba(0,0,0,0.08), 0 4px 8px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.1);
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--charcoal);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { text-decoration: none; color: inherit; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }
img { max-width: 100%; display: block; }

.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ===== HEADER ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 22px;
  font-weight: 800;
  color: var(--primary);
  letter-spacing: -0.5px;
}

.logo i {
  font-size: 26px;
}

.nav-main {
  display: flex;
  align-items: center;
  gap: 4px;
  height: 100%;
}

.nav-item {
  position: relative;
  height: 64px;
  display: flex;
  align-items: center;
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 14px;
  font-size: 14.5px;
  font-weight: 500;
  color: var(--charcoal);
  border-radius: var(--radius-sm);
  transition: all 0.2s;
  white-space: nowrap;
}

.nav-link:hover { background: var(--gray-100); color: var(--primary); }

.nav-link i {
  font-size: 12px;
  transition: transform 0.2s;
}

.nav-item.active .nav-link { color: var(--primary); }
.nav-item.active .nav-link i { transform: rotate(180deg); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.btn-subscribe {
  padding: 8px 20px;
  background: var(--primary);
  color: var(--white);
  font-size: 13px;
  font-weight: 600;
  border-radius: 50px;
  transition: all 0.2s;
}

.btn-subscribe:hover { background: var(--primary-dark); }

.btn-signin {
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  color: var(--charcoal);
  border-radius: 50px;
  transition: all 0.2s;
}

.btn-signin:hover { color: var(--primary); }

/* ===== MEGA MENU ===== */
.mega-menu {
  position: absolute;
  top: 64px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--white);
  border-radius: 0 0 var(--radius-lg) var(--radius-lg);
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--gray-200);
  border-top: 3px solid var(--primary);
  padding: 28px 32px;
  min-width: 680px;
  opacity: 0;
  visibility: hidden;
  transform: translateX(-50%) translateY(8px);
  transition: all 0.25s ease;
  z-index: 999;
}

.nav-item.active .mega-menu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.mega-menu-link {
  display: block;
  padding: 8px 12px;
  font-size: 13.5px;
  color: var(--charcoal-light);
  border-radius: var(--radius-sm);
  transition: all 0.15s;
}

.mega-menu-link:hover {
  background: var(--primary-light);
  color: var(--primary);
}

.mega-menu-featured {
  margin-top: 20px;
  padding-top: 20px;
  border-top: 1px solid var(--gray-200);
  display: flex;
  gap: 24px;
}

.mega-menu-featured a {
  font-size: 13px;
  font-weight: 600;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 6px;
}

.mega-menu-featured a:hover { text-decoration: underline; }

.mega-menu-wide { min-width: 820px; }
.mega-menu-wide .mega-menu-grid { grid-template-columns: repeat(5, 1fr); }

.mega-menu-narrow { min-width: 360px; }
.mega-menu-narrow .mega-menu-grid { grid-template-columns: repeat(2, 1fr); }

/* ===== CREDIBILITY TICKER ===== */
.ticker-bar {
  background: var(--primary);
  color: var(--white);
  overflow: hidden;
  height: 40px;
  display: flex;
  align-items: center;
}

.ticker-track {
  display: flex;
  align-items: center;
  animation: ticker-scroll 30s linear infinite;
  white-space: nowrap;
}

.ticker-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 32px;
  font-size: 13px;
  font-weight: 500;
  flex-shrink: 0;
}

.ticker-item i { font-size: 16px; opacity: 0.9; }

.ticker-separator {
  width: 4px;
  height: 4px;
  background: rgba(255,255,255,0.5);
  border-radius: 50%;
  flex-shrink: 0;
}

@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ===== HERO ===== */
.hero {
  background: linear-gradient(135deg, var(--primary-50) 0%, var(--white) 100%);
  padding: 56px 0;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.hero-content { max-width: 520px; }

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  background: var(--primary);
  color: var(--white);
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-radius: 50px;
  margin-bottom: 20px;
}

.hero-badge i { font-size: 14px; }

.hero-title {
  font-size: 38px;
  font-weight: 800;
  line-height: 1.15;
  color: var(--charcoal);
  letter-spacing: -0.5px;
  margin-bottom: 16px;
}

.hero-subtitle {
  font-size: 17px;
  line-height: 1.6;
  color: var(--gray-600);
  margin-bottom: 28px;
}

.hero-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 28px;
  background: var(--primary);
  color: var(--white);
  font-size: 15px;
  font-weight: 600;
  border-radius: 50px;
  transition: all 0.2s;
}

.hero-cta:hover { background: var(--primary-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }

.hero-visual {
  display: flex;
  justify-content: center;
  align-items: center;
}

.hero-image-wrapper {
  position: relative;
  width: 100%;
  max-width: 480px;
  aspect-ratio: 4/3;
  border-radius: var(--radius-xl);
  background: linear-gradient(145deg, #B2EBF2 0%, #80DEEA 50%, #4DD0E1 100%);
  overflow: hidden;
  box-shadow: var(--shadow-xl);
}

.hero-image-wrapper::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(2,131,141,0.15) 100%);
}

.hero-fitness-badge {
  position: absolute;
  top: 20px;
  right: 20px;
  z-index: 2;
  background: var(--coral);
  color: var(--white);
  width: 80px;
  height: 80px;
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-lg);
}

.hero-fitness-badge span:first-child {
  font-size: 24px;
  font-weight: 800;
  line-height: 1;
}

.hero-fitness-badge span:last-child {
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.hero-fitness-icon {
  position: absolute;
  bottom: 24px;
  left: 24px;
  z-index: 2;
  width: 56px;
  height: 56px;
  background: var(--white);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-md);
}

.hero-fitness-icon i { font-size: 28px; color: var(--primary); }

/* ===== TRENDING ===== */
.trending {
  padding: 56px 0;
  background: var(--white);
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 28px;
}

.section-title {
  font-size: 24px;
  font-weight: 700;
  color: var(--charcoal);
  letter-spacing: -0.3px;
}

.section-link {
  font-size: 14px;
  font-weight: 600;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 4px;
}

.section-link:hover { text-decoration: underline; }

.trending-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.trending-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: all 0.25s;
  background: var(--white);
}

.trending-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.trending-card-img {
  height: 160px;
  background: var(--gray-200);
  position: relative;
  overflow: hidden;
}

.trending-card-img::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,0.04) 100%);
}

.trending-card:nth-child(1) .trending-card-img { background: linear-gradient(135deg, #FDE8E8, #F8B4B4); }
.trending-card:nth-child(2) .trending-card-img { background: linear-gradient(135deg, #E0F2F1, #A5D6C7); }
.trending-card:nth-child(3) .trending-card-img { background: linear-gradient(135deg, #FFF3E0, #FFCC80); }
.trending-card:nth-child(4) .trending-card-img { background: linear-gradient(135deg, #E8EAF6, #B3B9E0); }

.trending-card-img i {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 32px;
  color: rgba(0,0,0,0.15);
}

.trending-card-body { padding: 16px; }

.trending-card-tag {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--primary);
  margin-bottom: 8px;
}

.trending-card-title {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--charcoal);
}

/* ===== NEWSLETTER CTA ===== */
.newsletter-cta {
  padding: 64px 0;
  background: var(--primary-light);
}

.newsletter-inner {
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
}

.newsletter-heading {
  font-size: 28px;
  font-weight: 800;
  color: var(--charcoal);
  margin-bottom: 12px;
  letter-spacing: -0.3px;
}

.newsletter-body {
  font-size: 16px;
  color: var(--gray-600);
  margin-bottom: 28px;
  line-height: 1.6;
}

.newsletter-form {
  display: flex;
  gap: 10px;
  max-width: 480px;
  margin: 0 auto 12px;
}

.newsletter-input {
  flex: 1;
  padding: 14px 20px;
  border: 2px solid var(--gray-300);
  border-radius: 50px;
  font-size: 15px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s;
  background: var(--white);
}

.newsletter-input:focus { border-color: var(--primary); }

.newsletter-btn {
  padding: 14px 28px;
  background: var(--coral);
  color: var(--white);
  font-size: 15px;
  font-weight: 600;
  border-radius: 50px;
  transition: all 0.2s;
  white-space: nowrap;
}

.newsletter-btn:hover { background: var(--coral-dark); }

.newsletter-privacy {
  font-size: 12px;
  color: var(--gray-500);
}

/* ===== HEALTH TOPICS ===== */
.health-topics {
  padding: 56px 0;
  background: var(--white);
}

.topics-carousel-wrapper {
  position: relative;
}

.topics-carousel {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 8px 0 16px;
}

.topics-carousel::-webkit-scrollbar { display: none; }

.topic-card {
  flex-shrink: 0;
  width: 160px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  padding: 20px 12px;
  border-radius: var(--radius-lg);
  transition: all 0.25s;
  cursor: pointer;
}

.topic-card:hover { background: var(--primary-light); transform: translateY(-3px); }

.topic-card-img {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: var(--primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.25s;
}

.topic-card:hover .topic-card-img { box-shadow: 0 0 0 3px var(--primary); }

.topic-card-img i { font-size: 36px; color: var(--primary); }

.topic-card-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
  text-align: center;
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: var(--charcoal);
  box-shadow: var(--shadow-md);
  z-index: 10;
  transition: all 0.2s;
}

.carousel-arrow:hover { background: var(--primary); color: var(--white); border-color: var(--primary); }
.carousel-arrow.left { left: -16px; }
.carousel-arrow.right { right: -16px; }

/* ===== HEALTH TOOLS ===== */
.health-tools {
  padding: 56px 0;
  background: var(--gray-50);
}

.tools-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}

.tools-intro {
  background: var(--primary);
  color: var(--white);
  border-radius: var(--radius-xl);
  padding: 36px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.tools-intro-icon {
  width: 48px;
  height: 48px;
  background: rgba(255,255,255,0.15);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.tools-intro-icon i { font-size: 24px; }

.tools-intro h3 {
  font-size: 24px;
  font-weight: 700;
  margin-bottom: 12px;
  line-height: 1.3;
}

.tools-intro p {
  font-size: 15px;
  line-height: 1.6;
  opacity: 0.9;
  margin-bottom: 24px;
}

.tools-intro-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 22px;
  background: var(--white);
  color: var(--primary);
  font-size: 14px;
  font-weight: 600;
  border-radius: 50px;
  transition: all 0.2s;
  align-self: flex-start;
}

.tools-intro-cta:hover { transform: translateY(-1px); box-shadow: var(--shadow-md); }

.tools-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.tool-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 18px 20px;
  background: var(--white);
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  transition: all 0.25s;
}

.tool-card:hover { box-shadow: var(--shadow-md); border-color: var(--primary); }

.tool-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.tool-icon.nutrition { background: #FFF3E0; color: #E65100; }
.tool-icon.calculator { background: #E0F2F1; color: #00695C; }
.tool-icon.drug { background: #E8EAF6; color: #283593; }
.tool-icon.pill { background: #FCE4EC; color: #AD1457; }
.tool-icon.glp { background: #FFF8E1; color: #F57F17; }
.tool-icon.care { background: #E8F5E9; color: #2E7D32; }

.tool-icon i { font-size: 22px; }

.tool-info { flex: 1; }

.tool-name {
  font-size: 14.5px;
  font-weight: 600;
  color: var(--charcoal);
  margin-bottom: 2px;
}

.tool-desc {
  font-size: 13px;
  color: var(--gray-500);
  line-height: 1.4;
}

.tool-arrow {
  font-size: 18px;
  color: var(--gray-400);
  transition: all 0.2s;
}

.tool-card:hover .tool-arrow { color: var(--primary); transform: translateX(3px); }

/* ===== RECOMMENDED READS ===== */
.recommended-reads {
  padding: 56px 0;
  background: var(--white);
}

.reads-tabs {
  display: flex;
  gap: 6px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}

.reads-tab {
  padding: 9px 20px;
  font-size: 13.5px;
  font-weight: 500;
  color: var(--gray-600);
  border-radius: 50px;
  border: 1px solid var(--gray-200);
  transition: all 0.2s;
}

.reads-tab:hover { border-color: var(--primary); color: var(--primary); }

.reads-tab.active {
  background: var(--primary);
  color: var(--white);
  border-color: var(--primary);
}

.reads-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.read-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: all 0.25s;
  background: var(--white);
}

.read-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); }

.read-card-img {
  height: 180px;
  background: var(--gray-200);
  position: relative;
  overflow: hidden;
}

.read-card-img::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,0.05) 100%);
}

.read-card-img i {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 36px;
  color: rgba(0,0,0,0.1);
}

.read-card-body { padding: 18px; }

.read-card-category {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--primary);
  margin-bottom: 8px;
}

.read-card-title {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--charcoal);
  margin-bottom: 8px;
}

.read-card-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 12px;
  color: var(--gray-500);
}

.read-card-meta span {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ===== TRUST SECTION ===== */
.trust-section {
  padding: 64px 0;
  background: var(--primary-light);
}

.trust-heading {
  text-align: center;
  font-size: 28px;
  font-weight: 800;
  color: var(--charcoal);
  margin-bottom: 40px;
  letter-spacing: -0.3px;
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.3;
}

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.trust-card {
  text-align: center;
  padding: 28px 20px;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  transition: all 0.25s;
}

.trust-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }

.trust-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 16px;
  background: var(--primary-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.trust-icon i { font-size: 24px; color: var(--primary); }

.trust-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 8px;
}

.trust-desc {
  font-size: 13.5px;
  line-height: 1.5;
  color: var(--gray-600);
}

/* ===== FEATURED PROGRAMS ===== */
.featured-programs {
  padding: 56px 0;
  background: var(--white);
}

.programs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.program-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: all 0.25s;
  background: var(--white);
}

.program-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); }

.program-card-img {
  height: 150px;
  position: relative;
  overflow: hidden;
}

.program-card:nth-child(1) .program-card-img { background: linear-gradient(135deg, #F3E5F5, #CE93D8); }
.program-card:nth-child(2) .program-card-img { background: linear-gradient(135deg, #E3F2FD, #90CAF9); }
.program-card:nth-child(3) .program-card-img { background: linear-gradient(135deg, #FFF3E0, #FFB74D); }
.program-card:nth-child(4) .program-card-img { background: linear-gradient(135deg, #E8F5E9, #81C784); }

.program-card-img i {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 32px;
  color: rgba(0,0,0,0.12);
}

.program-card-body { padding: 16px; }

.program-card-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--charcoal);
  line-height: 1.4;
}

/* ===== LATEST VIDEOS ===== */
.latest-videos {
  padding: 56px 0;
  background: var(--gray-50);
}

.videos-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.video-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: all 0.25s;
  background: var(--white);
}

.video-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); }

.video-card-img {
  height: 150px;
  position: relative;
  overflow: hidden;
  background: var(--gray-300);
}

.video-card:nth-child(1) .video-card-img { background: linear-gradient(135deg, #EFEBE9, #BCAAA4); }
.video-card:nth-child(2) .video-card-img { background: linear-gradient(135deg, #FCE4EC, #F48FB1); }
.video-card:nth-child(3) .video-card-img { background: linear-gradient(135deg, #E0F2F1, #80CBC4); }
.video-card:nth-child(4) .video-card-img { background: linear-gradient(135deg, #E8EAF6, #9FA8DA); }

.video-play {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 48px;
  height: 48px;
  background: rgba(255,255,255,0.95);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-md);
  transition: all 0.2s;
}

.video-card:hover .video-play { background: var(--primary); }
.video-card:hover .video-play i { color: var(--white); }

.video-play i { font-size: 20px; color: var(--charcoal); margin-left: 2px; }

.video-card-body { padding: 14px 16px; }

.video-card-title {
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--charcoal);
}

/* ===== FOOTER ===== */
.footer {
  background: var(--charcoal);
  color: var(--white);
  padding: 56px 0 0;
}

.footer-newsletter {
