  border-radius: 50px;
  font-size: 14px;
  font-family: inherit;
  background: rgba(255,255,255,0.08);
  color: var(--white);
  outline: none;
  transition: border-color 0.2s;
}

.footer-input::placeholder { color: rgba(255,255,255,0.4); }
.footer-input:focus { border-color: var(--primary); }

.footer-btn {
  padding: 12px 24px;
  background: var(--primary);
  color: var(--white);
  font-size: 14px;
  font-weight: 600;
  border-radius: 50px;
  transition: all 0.2s;
  white-space: nowrap;
}

.footer-btn:hover { background: var(--primary-dark); }

.footer-divider {
  border: none;
  border-top: 1px solid rgba(255,255,255,0.1);
  margin: 0;
}

.footer-links {
  padding: 32px 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 24px;
}

.footer-link {
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  transition: color 0.2s;
}

.footer-link:hover { color: var(--white); }

.footer-separator {
  color: rgba(255,255,255,0.2);
  font-size: 13px;
}

.footer-bottom {
  padding: 24px 0;
  border-top: 1px solid rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-legal {
  font-size: 12px;
  line-height: 1.6;
  color: rgba(255,255,255,0.4);
  max-width: 680px;
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
  color: rgba(255,255,255,0.6);
  font-size: 16px;
  transition: all 0.2s;
}

.footer-social a:hover { background: var(--primary); color: var(--white); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; gap: 32px; }
